insert into wine_place_boundaries (wine_place_id, source_snapshot_id, boundary_method, quality_status, display_geometry, label_point, bbox, source_feature_refs, generation_parameters, revision, is_current, reviewed_at)
select p.id, snap.id, 'GENERALIZED_FROM_OFFICIAL_SOURCE', 'VALIDATED', geom.g, extensions.ST_PointOnSurface(geom.g),
       array[extensions.ST_XMin(extensions.Box3D(geom.g)), extensions.ST_YMin(extensions.Box3D(geom.g)), extensions.ST_XMax(extensions.Box3D(geom.g)), extensions.ST_YMax(extensions.Box3D(geom.g))]::double precision[],
       '{"source":"ISTAT regione Sicilia"}'::jsonb, '{"engine":"istat-admin-region","simplify":"mapshaper 6%","holes":"dropped","coordinate_precision":5}'::jsonb,
       '20260814T182557Z', true, now()
from wine_places p, snap, geom where p.canonical_key = 'italy.sicilia';

do $$
declare n int; bx double precision[];
begin
  select count(*) into n from wine_place_boundaries b join wine_places p on p.id=b.wine_place_id where p.canonical_key='italy.sicilia' and b.is_current and b.quality_status='VALIDATED';
  if n <> 1 then raise exception 'expected 1 current Sicily region boundary, got %', n; end if;
  select b.bbox into bx from wine_place_boundaries b join wine_places p on p.id=b.wine_place_id where p.canonical_key='italy.sicilia' and b.is_current;
  if bx[1] < 11.8 or bx[2] < 35.4 or bx[3] > 15.7 or bx[4] > 38.9 then raise exception 'Sicily region bbox escapes window: %', bx; end if;
end
$$;
